operation.add:
// Загружаем модель мультисклада
$this->load->model('extension/module/multistock');
$data['warehouses'] = $this->model_extension_module_multistock->getStorages();
if (isset($this->request->get['product_id'])) {
    $data['product_warehouse'] = $this->model_extension_module_multistock->getProductStocks($this->request->get['product_id']);
} else {
    $data['product_warehouse'] = array();
}

// Сохраняем остатки по складам
$product_id = $this->db->getLastId();
if (isset($this->request->post['product_warehouse'])) {
    $this->load->model('extension/module/multistock');
    foreach ($this->request->post['product_warehouse'] as $warehouse_id => $quantity) {
        $this->model_extension_module_multistock->updateProductStock($product_id, $warehouse_id, $quantity);
    }
}

// Обновляем остатки по складам
if (isset($this->request->post['product_warehouse'])) {
    $this->load->model('extension/module/multistock');
    foreach ($this->request->post['product_warehouse'] as $warehouse_id => $quantity) {
        $this->model_extension_module_multistock->updateProductStock($product_id, $warehouse_id, $quantity);
    }
}

// Добавляем информацию о наличии на складах
$this->load->model('extension/module/multistock');
$product['warehouse_stocks'] = $this->model_extension_module_multistock->getProductStocks($product_id);
$product['total_quantity'] = array_sum($product['warehouse_stocks']);

// Логика списания с мультисклада
$this->load->model('extension/module/multistock');
$to_subtract = (int)$item['quantity'];

// Получаем остатки по складам
$warehouse_stocks = $this->model_extension_module_multistock->getProductStocks($item['product_id']);

// Сортируем склады по убыванию количества
arsort($warehouse_stocks);

foreach ($warehouse_stocks as $warehouse_id => $quantity) {
    if ($to_subtract <= 0) break;

    $subtract_from_this = ($quantity >= $to_subtract) ? $to_subtract : $quantity;
    $new_quantity = $quantity - $subtract_from_this;

    $this->model_extension_module_multistock->updateProductStock($item['product_id'], $warehouse_id, $new_quantity);
    $to_subtract -= $subtract_from_this;
}

// Обновляем общее количество
$total_quantity = $this->model_extension_module_multistock->getTotalProductStock($item['product_id']);
$this->db->query("UPDATE " . DB_PREFIX . "product SET quantity = " . (int)$total_quantity . " WHERE product_id = '" . (int)$item['product_id'] . "'");
